from typing import List

def get_best_price(menu: List[List[str]], userWants: List[str]):
    idx = {w: i for i, w in enumerate(userWants)}
    full = (1 << len(userWants)) - 1
    options = []
    for row in menu:
        cents = round(float(row[0]) * 100)  # 用整数“分”计算，避免浮点误差
        mask = 0
        for name in ",".join(row[1:]).split(","):
            name = name.strip()
            if name in idx:
                mask |= 1 << idx[name]
        if mask:
            options.append((mask, cents))

    INF = float("inf")
    dp = [INF] * (full + 1)  # dp[mask]：凑齐 mask 这些想要的菜的最低价
    dp[0] = 0
    for mask in range(full + 1):
        if dp[mask] == INF:
            continue
        for s, cents in options:
            nm = mask | s
            if dp[mask] + cents < dp[nm]:
                dp[nm] = dp[mask] + cents
    if dp[full] == INF:
        return -1
    return dp[full] // 100 if dp[full] % 100 == 0 else dp[full] / 100
